package api

import (
	"context"
	"encoding/json"
	"net/http"
	"testing"
)

// TestSourceChainPresentation covers the served source_chain list (media-data-
// convention 1.1, the "served chain is the gate-resolved order" scenario):
// GET /api/v1/libraries/{id} carries the module block's additive
// source_chain — every bound source in chain order, each pair its
// enrich.ResolveGates verdict, the muted source served with enabled:false so
// the projection's walk sees the skip. The pairs ride through AddChainSource
// exactly as the cmd/mellifera closure appends them (the fake closure here is
// the same construction path); an unwired chain stays absent on the wire.
func TestSourceChainPresentation(t *testing.T) {
	ctx := context.Background()

	// fakeModulePresentation stands in for the cmd/mellifera closure over
	// module.Registry (INV4 — the api contract is the api-local shape),
	// building the block through AddChainSource the way the real closure
	// walks its gate-resolved bindings in chain order.
	fakeModulePresentation := func(build func(*ModulePresentation)) func(context.Context, string, int64) (ModulePresentation, error) {
		return func(context.Context, string, int64) (ModulePresentation, error) {
			var mp ModulePresentation
			mp.IdentityFields = []string{"title"}
			build(&mp)
			return mp, nil
		}
	}

	tests := []struct {
		name  string
		build func(*ModulePresentation)
		want  []map[string]any // nil = the wire key must be absent entirely
	}{
		{
			name: "chain_order_with_muted_source",
			build: func(mp *ModulePresentation) {
				mp.AddChainSource("shikimori", true)
				mp.AddChainSource("kinopoisk", false)
				mp.AddChainSource("tvdb", true)
			},
			want: []map[string]any{
				{"id": "shikimori", "enabled": true},
				{"id": "kinopoisk", "enabled": false},
				{"id": "tvdb", "enabled": true},
			},
		},
		{
			name:  "unwired_chain_absent_on_the_wire",
			build: func(*ModulePresentation) {},
			want:  nil,
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			st := openAPIStore(t)
			id, err := st.CreateLibrary(ctx, "tv", "/media/chain-"+tt.name, "TV")
			if err != nil {
				t.Fatalf("CreateLibrary: %v", err)
			}
			h := New(Deps{AdminToken: adminToken, Store: st, ModulePresentation: fakeModulePresentation(tt.build)})
			resp := doRequest(t, h, http.MethodGet, "/api/v1/libraries/"+itoa64(id), "", adminToken)
			defer resp.Body.Close()
			if resp.StatusCode != http.StatusOK {
				t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusOK)
			}
			var body struct {
				Module map[string]json.RawMessage `json:"module"`
			}
			if err := json.NewDecoder(resp.Body).Decode(&body); err != nil {
				t.Fatalf("decode response: %v", err)
			}
			raw, ok := body.Module["source_chain"]
			if tt.want == nil {
				if ok {
					t.Fatalf("source_chain = %s, want the key absent when no pair is appended", raw)
				}
				return
			}
			if !ok {
				t.Fatalf("source_chain missing, want %d pairs in chain order", len(tt.want))
			}
			var got []map[string]any
			if err := json.Unmarshal(raw, &got); err != nil {
				t.Fatalf("decode source_chain: %v", err)
			}
			if len(got) != len(tt.want) {
				t.Fatalf("source_chain = %s, want %d pairs", raw, len(tt.want))
			}
			for i, want := range tt.want {
				if got[i]["id"] != want["id"] {
					t.Fatalf("source_chain[%d].id = %v, want %v (chain order is served data)", i, got[i]["id"], want["id"])
				}
				if got[i]["enabled"] != want["enabled"] {
					t.Fatalf("source_chain[%d] (%v).enabled = %v, want %v — the muted source must serve enabled:false",
						i, got[i]["id"], got[i]["enabled"], want["enabled"])
				}
			}
		})
	}
	// httptest is imported by the harness above via doRequest; keep the
	// import honest with one direct assertion of the wire shape: the pairs
	// marshal as {"id","enabled"} — byte-identical to title_sources.
	t.Run("pair_wire_shape", func(t *testing.T) {
		var mp ModulePresentation
		mp.AddChainSource("shikimori", true)
		b, err := json.Marshal(mp.SourceChain)
		if err != nil {
			t.Fatalf("marshal: %v", err)
		}
		if got, want := string(b), `[{"id":"shikimori","enabled":true}]`; got != want {
			t.Fatalf("wire shape = %s, want %s", got, want)
		}
	})
}
